parsed=[]
for row in rows:
    cells=row.split('|')
    assert len(cells)==len(locales)+1,(cells[0],len(cells))
    parsed.append(cells)
for index,locale in enumerate(locales):
    directory=Path('app/src/main/res')/('values'+('-'+locale if locale else ''))
    directory.mkdir(exist_ok=True,parents=True)
    lines=['<?xml version="1.0" encoding="utf-8"?>','<resources>']
    for cells in parsed:
        value=escape(cells[index+1]).replace("'",r"\'")
        lines.append(f'    <string name="{cells[0]}">{value}</string>')
    lines.append('</resources>')
    (directory/'strings.xml').write_text('\n'.join(lines)+'\n')
print(f'{len(parsed)} strings × {len(locales)} languages')
